# -*- coding: utf-8 -*-
"""Science Stage 8 · Unit 12 Renewable and Non-Renewable Energy Resources – Read the lesson (shown below the video) and the lesson document (PDF).
Camday's own text, examples and questions; scope: Cambridge Lower Secondary Science 0893, Stage 8 (8ESp.02, 8SIC.02, 8SIC.03, 8SIC.05)."""
from maths_notes_v4.kit4 import H, I, Y, X, K, L, W, BK, Ex, mcq, grid, num

READ = {}
CARD = lambda title, cards, cols=None: dict({"kind": "sciCards", "title": title, "cards": cards}, **({"cols": cols} if cols else {}))

# =====================================================================================================
# 12.1 Energy needs and energy resources · 8ESp.02, 8SIC.02
# =====================================================================================================
READ["12.1"] = L(
    H("A day without power",
      "Imagine the electricity supply to your town stopped for a whole day.",
      "List five things that would stop working. Which would matter most?"),
    I("What is an energy resource?",
      "An **energy resource** is anything we can get useful energy from.",
      table=[["Resource", "Energy store"], ["wood, biofuels", "chemical"], ["coal, oil, natural gas (fossil fuels)", "chemical"], ["uranium (nuclear fuel)", "nuclear"],
             ["sunlight", "light (radiation)"], ["wind, moving water", "kinetic"], ["water behind a dam", "gravitational potential"], ["hot rocks underground", "thermal"]],
      then=["Most of the energy we use reaches us as **electricity**, generated in power stations or by solar panels and wind turbines."]),
    I("Every part of society needs energy",
      "Energy use is rising as people use more technology.",
      fig=CARD("Where our energy goes", [{"icon": "plug", "t": "Homes", "d": "cooking, lighting, heating, cooling, charging"}, {"icon": "car", "t": "Transport", "d": "petrol, diesel, jet fuel, batteries"},
                                          {"icon": "factory", "t": "Industry and farming", "d": "machines, fertilisers, food processing"}, {"icon": "heart", "t": "Hospitals and data centres", "d": "power day and night, with back-up generators"}], 4),
      then=["Without a reliable supply, homes go dark, factories stop, transport halts and hospitals must rely on back-up power."]),
    I("Real data: world energy sources",
      "Approximate share of the world's primary energy, recent years:",
      fig={"kind": "pie", "labels": ["oil 31%", "coal 26%", "natural gas 23%", "nuclear 4%", "hydro 6%", "wind, solar, other renewables 10%"], "values": [31, 26, 23, 4, 6, 10]},
      then=["About four fifths still comes from **fossil fuels**, but the share from renewable resources is growing every year."]),
    Y("Fossil fuel share",
      num("s8u12r11", "Use the pie chart. What percentage of world energy comes from fossil fuels (oil + coal + gas)?", 80, "Add the three fossil fuel slices.", "31 + 26 + 23 = 80%.")),
    K("Key points",
      "An **energy resource** is anything we get useful energy from.",
      "Homes, transport, industry, farming, hospitals and data centres all need a reliable energy supply.",
      "Most of the world's energy still comes from fossil fuels; renewables are growing."),
    book=BK(
        [("energy resource", "anything from which useful energy can be obtained"), ("fossil fuel", "coal, oil or natural gas, formed from ancient living things")],
        [], [],
        [Ex("Name four energy resources and the energy store in each.", ans="e.g. coal – chemical; wind – kinetic; uranium – nuclear; dammed water – gravitational potential"),
         Ex("Give three parts of society that need energy, with one use each.", ans="e.g. homes – cooking; transport – fuel for buses; hospitals – life-support machines"),
         Ex("Why do hospitals have back-up generators?", ans="Machines such as life support must never stop if the main supply fails."),
         Ex("Suggest why world energy use keeps rising.", ans="More people, more technology and devices, more industry and transport.", think=True)],
        ["describe what an energy resource is", "explain why society needs a reliable energy supply"],
        look=["the energy resource table", "the world energy pie chart"],
        note="Read it after the video: energy resources and why society needs energy (answers at the back)."),
)

# =====================================================================================================
# 12.2 Non-renewable energy resources · 8ESp.02, 8SIC.05
# =====================================================================================================
READ["12.2"] = L(
    H("Millions of years in a minute",
      "The coal burned in a power station in one minute took millions of years to form from ancient plants.",
      "What does this tell you about how long fossil fuels will last?"),
    I("Fossil fuels",
      "**Coal** formed from ancient plants; **oil** and **natural gas** from tiny sea creatures, buried and squeezed under rock for millions of years.",
      fig={"kind": "sciFlow", "title": "A fossil fuel power station", "steps": [{"icon": "flame", "t": "Burn fuel", "d": "chemical energy → heat"}, {"t": "Boil water", "d": "make steam"},
                                                                              {"icon": "turbine", "t": "Turbine", "d": "steam spins it"}, {"icon": "bolt", "t": "Generator", "d": "makes electricity"}]},
      then=["They are **non-renewable**: they cannot be replaced as fast as we use them, and each fuel can only be used once."]),
    I("The cost of burning fossil fuels",
      "Burning fossil fuels releases **carbon dioxide** (a greenhouse gas that causes global warming) and pollutants such as **sulfur dioxide** and **nitrogen oxides** (acid rain, breathing problems).",
      then=["Global warming and climate change are linked to more extreme weather: heatwaves, floods, droughts, storms and wildfires.",
            "**Fracking** pumps water, sand and chemicals into shale rock to release natural gas. It can cause small earthquakes, uses lots of water and releases greenhouse gases – and the gas is still a fossil fuel."]),
    I("Real data: carbon dioxide per unit of electricity",
      "Carbon dioxide released for each kilowatt hour (kWh) of electricity over a power station's whole life – building and running it:",
      fig={"kind": "barchart", "labels": ["coal", "natural gas", "solar", "hydro", "nuclear", "wind"], "values": [820, 490, 48, 24, 12, 11], "ymax": 900, "step": 150,
           "ylabel": "CO₂ (grams per kWh)", "xlabel": "energy resource"},
      then=["Coal releases about 70 times more than wind. Solar, wind and nuclear still release a little, from mining materials and building and maintaining the power stations."]),
    Y("How many times more?",
      num("s8u12r21", "Use the chart. Roughly how many times more CO₂ per kWh does coal release than solar (to the nearest whole number)?", 17, "Divide coal's value by solar's.",
          "820 ÷ 48 ≈ 17 times.", errs=[(772, "'How many times' means divide.")])),
    I("Nuclear energy",
      "Uranium atoms have large nuclei. When a neutron hits one, the nucleus splits (**nuclear fission**), releasing energy and more neutrons, which split more nuclei – a **chain reaction**.",
      table=[["Advantages", "Disadvantages"], ["very little carbon dioxide", "uranium is mined and limited – non-renewable"], ["a small amount of fuel gives a lot of energy", "radioactive waste stays dangerous for thousands of years"],
             ["reliable – works day and night", "accidents are rare but very serious; power stations are expensive to build and close"]],
      then=["The heat from fission boils water into steam to turn turbines, just as in a coal power station."]),
    K("Key points",
      "Fossil fuels (coal, oil, gas) and nuclear fuel (uranium) are **non-renewable**.",
      "Power stations: fuel → heat → steam → turbine → generator → electricity.",
      "Burning fossil fuels releases CO₂ (global warming) and pollutants (acid rain).",
      "Nuclear fission releases little CO₂ but produces long-lasting radioactive waste."),
    book=BK(
        [("non-renewable", "cannot be replaced as fast as it is used"), ("greenhouse gas", "a gas that traps heat in the atmosphere, e.g. carbon dioxide"),
         ("nuclear fission", "splitting a large nucleus, releasing energy"), ("fracking", "forcing liquid into rock to release natural gas")],
        [], [],
        [Ex("Describe how a coal power station generates electricity.", ans="Coal burns, heat boils water into steam, steam turns a turbine, the turbine turns a generator."),
         Ex("Explain why fossil fuels are called non-renewable.", ans="They take millions of years to form, so they cannot be replaced as fast as we use them."),
         Ex("Give two environmental problems caused by burning fossil fuels.", ans="global warming / climate change from carbon dioxide; acid rain from sulfur dioxide and nitrogen oxides"),
         Ex("Give one advantage and one disadvantage of nuclear power.", ans="Advantage: very little carbon dioxide / reliable. Disadvantage: radioactive waste / non-renewable / risk of accidents."),
         Ex("Why do wind and solar power still have a small carbon footprint?", ans="Making, transporting and installing the turbines and panels uses energy and materials that release some CO₂.", think=True)],
        ["explain how fossil fuels and nuclear fuels generate electricity", "explain why they are non-renewable", "describe their environmental impacts"],
        look=["the power station steps", "the CO₂ per kWh chart"],
        note="Read it after the video: fossil fuels, their costs and nuclear energy (answers at the back)."),
)

# =====================================================================================================
# 12.3 Renewable energy resources · 8ESp.02, 8SIC.03
# =====================================================================================================
READ["12.3"] = L(
    H("Never running out",
      "The Sun will keep shining for billions of years, the wind will keep blowing and the tides will keep rising and falling.",
      "Why don't we get all our electricity from them already? Think of one problem."),
    I("Energy from the Sun",
      "**Renewable** energy resources are replaced naturally and will not run out.",
      table=[["Technology", "How it works"], ["**solar panels** (photovoltaic cells)", "light knocks electrons free, making an electric current"],
             ["**solar water heaters**", "black pipes absorb the Sun's energy and heat water"], ["**solar thermal plants**", "mirrors focus sunlight to boil water and drive turbines; hot molten salt stores heat for the night"]],
      then=["Disadvantages: no power at night, less on cloudy days, panels need lots of space, and making them uses mined metals."]),
    I("Predict, watch, explain: a model solar water heater",
      "Two cans of water at 20 °C – one matt black, one shiny silver – stand in sunshine.",
      fig={"kind": "linegraph", "x": {"min": 0, "max": 30, "step": 10, "label": "time (minutes)"}, "y": {"min": 15, "max": 40, "step": 5, "label": "temperature (°C)"},
           "series": [{"pts": [[0, 20], [10, 26], [20, 32], [30, 37]], "label": "black"}, {"pts": [[0, 20], [10, 22], [20, 24], [30, 26]], "label": "silver"}]},
      then=["The black can warmed much faster: matt black **absorbs** most of the Sun's energy, while shiny surfaces **reflect** it. That is why solar heaters have black panels."]),
    I("Wind and water",
      "Moving air and water carry kinetic energy.",
      table=[["Resource", "Advantages", "Disadvantages"],
             ["**wind**", "clean, no fuel cost", "not always windy; noise; can harm birds; turbines are costly"],
             ["**hydroelectric** (dams)", "clean, reliable, can be switched on quickly", "floods valleys and destroys habitats; only in certain places"],
             ["**tidal and wave**", "tides are predictable", "few suitable sites; expensive; can affect sea life"]]),
    I("Earth's heat and energy from living things",
      "**Geothermal** power uses heat from hot rocks underground to make steam (common in Iceland, Kenya, Indonesia).",
      then=["**Biofuels** and **biogas** come from plants, waste and manure. They release carbon dioxide when burned, but new plants take it in again as they grow. Growing biofuel crops can use land needed for food."]),
    Y("Match the resource",
      grid("s8u12r31", "Which renewable resource is described?", ["Solar", "Wind", "Hydroelectric", "Geothermal"],
           [("uses hot rocks underground", "Geothermal"), ("water stored behind a dam", "Hydroelectric"), ("turbines on hills or at sea", "Wind"), ("photovoltaic cells on roofs", "Solar")],
           "Which store does each use?", "Hot rocks – geothermal; dam – hydroelectric; turbines in wind – wind; PV cells – solar.")),
    Y("Evaluate",
      mcq("s8u12r32", "Which is the main disadvantage of solar and wind power?",
          [("Their output depends on the weather and time of day.", True, "Yes – so we need storage or back-up."), ("They release a lot of carbon dioxide.", False, "Very little."),
           ("They will run out.", False, "They are renewable."), ("They need uranium.", False, "That is nuclear power.")],
          "Think about night and calm days.", "They are not always available, so energy storage is needed.")),
    K("Key points",
      "**Renewable** resources: solar, wind, hydroelectric, tidal, wave, geothermal, biofuels.",
      "Matt black surfaces absorb the Sun's energy best (solar water heaters).",
      "Each resource has advantages and disadvantages – cost, reliability, location, effects on wildlife.",
      "A mix of resources and energy storage helps give a reliable, low-carbon supply."),
    book=BK(
        [("renewable", "replaced naturally; will not run out"), ("photovoltaic cell", "a solar cell that turns light into electricity"), ("geothermal", "heat from hot rocks underground"),
         ("biofuel", "fuel made from plants or animal waste")],
        [], [],
        [Ex("Give one advantage and one disadvantage of: (a) wind (b) hydroelectric (c) solar.",
            ans="(a) clean / not always windy (b) reliable / floods habitats (c) clean / no power at night"),
         Ex("Why are solar water heater panels black?", ans="Black absorbs the most energy from sunlight."),
         Ex("Use the graph: how much hotter was the black can than the silver can after 30 minutes?", ans="37 − 26 = 11 °C"),
         Ex("Quick quiz.", ("What is an energy resource?", "anything from which we get useful energy"), ("Why are fossil fuels non-renewable?", "they take millions of years to form"),
            ("What is nuclear fission?", "splitting large nuclei to release energy"), ("Name three renewable resources.", "e.g. solar, wind, geothermal")),
         Ex("Your town wants a new power supply. Evaluate wind turbines and a coal power station, then make a recommendation.",
            ans="Wind: clean, renewable, but variable and needs space; coal: reliable but polluting and non-renewable; a reasoned choice, e.g. wind with storage or back-up.", think=True)],
        ["describe renewable energy resources", "evaluate their advantages and disadvantages"],
        look=["the black and silver cans", "the advantages and disadvantages table"],
        note="Read it after the video: renewable resources and evaluating them, plus a quick quiz (answers at the back)."),
)
